(()=>{'use strict';
const PERIOD=window.GH_PERIOD||'2',isPeriod1=PERIOD==='1',DATA=window.GH_DATA, K=isPeriod1?'maris-gastheerschap-periode1-v1':'maris-gastheerschap-v1.2', isTeacher=document.body.dataset.mode==='teacher';
const NAV=[['home','Overzicht','⌂'],['programme','8 bijeenkomsten','▤'],['interactive','Interactieve lessen','✎'],['theory','Leerstof & begrippen','◫'],['quiz','SE-oefentrainer','✦'],['kitchen','Keukenlab','♨'],['table','Tafel indekken','♧'],['hightea','High tea Nolenshage','♜'],['rubric','Praktijkcijfer','◈'],['progress','Mijn voortgang','◉']];
if(isTeacher)NAV.push(['teacher','Leerlingen & rubric','▥'],['documents','Documentenbibliotheek','▣'],['guide','Docentenhandleiding','☷']);
if(isPeriod1){NAV.find(x=>x[0]==='programme')[1]='3 bijeenkomsten';NAV.find(x=>x[0]==='hightea')[1]='Docentenlunch';}
NAV.push(['settings','Gegevens & hulp','⚙']);
const baseProfile=()=>({checks:{},lessonNotes:{},lessonChecks:{},quizHistory:[],table:null,invitation:{title:'Uitnodiging voor een gezellige high tea',body:'De leerlingen van Maris College Bohemen nodigen u van harte uit voor een gezellige high tea. We serveren met plezier heerlijke hartige en zoete hapjes, samen met koffie en thee. We hopen u te mogen verwelkomen!'},menu:{title:'High tea · met zorg bereid',savoury:'Vegetarische mini-quiche\nKleine sandwiches met komkommer',sweet:'Scones met jam\nFruitmuffins\nAppelflappen',drinks:'Zwarte thee\nGroene thee\nRooibos of kruidenthee\nKoffie en water',allergens:'Vraag onze leerlingen naar de ingrediënten en allergenen.'},rubric:{cooking:{},service:{},prep:{},event:{},portfolio:{}},teacherNotes:'',reflection:'',highteaPlan:{role:'',notes:'',budget:[{item:'Thee (prijs invullen)',qty:1,price:0},{item:'Ingrediënten hartig',qty:1,price:0},{item:'Ingrediënten zoet',qty:1,price:0}]}});
const defaultProfile=()=>{const p=baseProfile();if(isPeriod1){p.invitation={title:'Uitnodiging docentenlunch',body:'Beste docenten,\nWij nodigen vier docenten uit voor onze lunch op school in bijeenkomst 3, van 11.30 tot 12.00 uur tijdens de grote pauze. Datum en lokaal volgen na bevestiging. Wij verzorgen de ontvangst, lunch en bediening. Graag vooraf dieetwensen en allergenen via de docent doorgeven.'};p.menu={title:'Docentenlunch · samen aan tafel',savoury:'Clubsandwich met groenten en gegaarde kip of vegetarisch beleg\nAlternatief na overleg: luxe broodje gezond',sweet:'Fruit als er ruimte is in het budget',drinks:'Water\nThee',allergens:'Vraag naar de werkelijke ingrediënten en allergenen; docent controleert verpakkingen.'};p.highteaPlan={role:'',notes:'Voor 11.30: bereiden, tafels indekken, poleren en controle.\n11.30–11.35: ontvangst.\n11.35–11.50: serveren en samen lunchen.\n11.50–12.00: afruimen en bedanken.\nNa afloop: afwas, schoonmaak en reflectie.',budget:[{item:'Brood · 3 sneetjes per persoon',qty:0,price:0},{item:'Beleg en groenten · porties voor leerlingen + 4 docenten',qty:0,price:0},{item:'Dranken en overige materialen',qty:0,price:0}]};}return p;};
const blank=()=>({active:'Voorbeeldleerling',profiles:{Voorbeeldleerling:defaultProfile()},meta:{...DATA.meta}});
function load(){try{const raw=localStorage.getItem(K);if(raw){let data=JSON.parse(raw);if(data&&data.profiles&&data.meta){if(!data.active||!data.profiles[data.active])data.active=Object.keys(data.profiles)[0];return data;}}}catch(e){console.warn('Opslag niet beschikbaar:',e);}return blank();}
let state=load(),ui={view:readRoute(),lesson:1,chapter:'h1',recipe:isPeriod1?'club':'kip',quizFilter:'all',quizCount:12,quiz:null,teacherSection:'cooking',cook:1,tableAnswers:{},tableFeedback:null,print:'',notice:'',rubricTab:'cooking',interactiveLesson:1,interactiveAnswers:{},interactiveChecked:false,documentsFilter:'all'};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const P=()=>{if(!state.profiles[state.active])state.profiles[state.active]=defaultProfile();return state.profiles[state.active];};
function save(){try{localStorage.setItem(K,JSON.stringify(state));return true;}catch(e){toast('Opslaan lukt niet; gebruik een downloadbare back-up.');return false;}}
function toast(msg){document.querySelector('.toast')?.remove();const b=document.createElement('div');b.className='toast';b.setAttribute('role','status');b.textContent=msg;document.body.append(b);setTimeout(()=>b.remove(),3500);}
const percent=(x,total)=>total?Math.round(x/total*100):0;
const nfmt=n=>(Math.round(n*10)/10).toFixed(1).replace('.',',');
const money=n=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR'}).format(n);
const tag=(txt,cls='')=>`<span class="pill ${cls}">${E(txt)}</span>`;
const button=(txt,act,cls='ghost',extra='')=>`<button type="button" class="btn ${cls}" data-act="${E(act)}" ${extra}>${txt}</button>`;
const title=(eyebrow,h1,lead)=>`<div class="page-title"><div class="eyebrow">${eyebrow}</div><h1>${h1}</h1><p class="lead">${lead}</p></div>`;
const catNames={cooking:'Koken',service:'Gastheerschapsvaardigheden',prep:'Voorbereiding high tea',event:'Uitvoering high tea',portfolio:'Portfolio & reflectie'};
const lesson=()=>DATA.sessions.find(x=>x.id===ui.lesson)||DATA.sessions[0];
const recipe=()=>DATA.recipes.find(x=>x.id===ui.recipe)||DATA.recipes[0];
const cData=id=>DATA.chapters.find(x=>x.id===id);
const doneTasks=()=>{let total=0,done=0;DATA.sessions.forEach(s=>s.tasks.forEach(t=>{total++;if(P().checks[`${s.id}_${t[0]}`])done++;}));return{total,done,pct:percent(done,total)};};
const rValue=(bucket,id,cook)=>{let r=P().rubric||{};let o=r[bucket]||{};if(bucket==='cooking')o=o[String(cook)]||{};return Object.prototype.hasOwnProperty.call(o,id)?o[id]:null;};
function calc(){let r=P().rubric||{},result={parts:[],ready:false,total:null,grade:null};let cooking=DATA.rubric.sections[0],completeCooks=[];for(let i=1;i<=(DATA.cookMoments||DATA.recipes.length);i++){let vals=cooking.criteria.map(a=>rValue('cooking',a[0],i));if(vals.every(x=>Number.isInteger(x)&&x>=0&&x<=3)){completeCooks.push({id:i,raw:vals.reduce((a,b)=>a+b,0),max:vals.length*3});}}
 let avg=completeCooks.length?completeCooks.reduce((sum,x)=>sum+x.raw/x.max,0)/completeCooks.length:0;
 result.parts.push({id:'cooking',title:'Koken',weight:30,complete:completeCooks.length>=(DATA.requiredCooks||5),score:avg*30,sub:`${completeCooks.length} van ${DATA.requiredCooks||5} vereist · gemiddelde ${nfmt(avg*48)} / 48`,completeCooks});
 for(const section of DATA.rubric.sections.slice(1)){
   let vals=section.criteria.map(a=>rValue(section.id,a[0]));let filled=vals.filter(x=>Number.isInteger(x)&&x>=0&&x<=3);let raw=filled.reduce((a,b)=>a+b,0);let max=section.criteria.length*3;
   result.parts.push({id:section.id,title:section.title,weight:section.weight,complete:filled.length===vals.length,score:(raw/max)*section.weight,sub:`${filled.length} / ${vals.length} criteria beoordeeld`});
 }
 result.ready=result.parts.every(x=>x.complete);
 if(result.ready){result.total=result.parts.reduce((a,b)=>a+b.score,0);result.grade=1+9*(result.total/100);}
 return result;
}
function readRoute(){const route=location.hash.slice(1);return NAV.some(x=>x[0]===route)?route:(isTeacher?'teacher':'home');}
function navTo(view){if(!NAV.some(x=>x[0]===view))return;ui.view=view;ui.print='';ui.quiz=null;if(location.hash.slice(1)!==view)history.pushState(null,'','#'+view);render();document.getElementById('main-content')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('popstate',()=>{ui.view=readRoute();ui.quiz=null;ui.print='';render();document.getElementById('main-content')?.focus({preventScroll:true});});
function render(){try{document.body.dataset.design=localStorage.getItem('maris-gastheerschap-design')||'1';}catch{document.body.dataset.design='1';}document.title=(NAV.find(x=>x[0]===ui.view)?.[1]||'Gastheerschap')+' · Maris College Bohemen';let root=document.getElementById('app');let active=NAV.find(x=>x[0]===ui.view)||NAV[0];let body=({home:isPeriod1?renderPeriodHome:renderHome,programme:renderProgramme,interactive:renderInteractive,theory:renderTheory,quiz:renderQuiz,kitchen:renderKitchen,table:renderTable,hightea:renderHighTea,rubric:renderRubric,progress:renderProgress,teacher:renderTeacher,documents:renderDocuments,guide:isPeriod1?renderPeriodGuide:renderGuide,settings:renderSettings}[ui.view]||renderHome)();
 if(isPeriod1&&ui.view==='programme'&&ui.lesson===1)body+=`<div class="section-head"><h2>De vier carrouselstations</h2></div><div class="grid two">${[
['1 · Clubsandwich','20 minuten · keuken','Beleg snijden, sandwich samenstellen, presenteren en schoonmaken. Gebruik gegaarde kip of vegetarisch beleg. Toaster alleen na instructie.','Foto van voorbereiding en eindgerecht.'],
['2 · Tafel indekken','20 minuten · tafel','Leg bord, bestek, glas en servet volgens de schoolinstructie. Controleer zitruimte en een vrije looproute. Laat de docent feedback geven.','Foto van je ingedekte plek; verbeter die na feedback.'],
['3 · Poleren','20 minuten · servies','Controleer glas en bestek op schade. Werk met een schone geschikte poleerdoek, houd het glas voorzichtig vast en voorkom vingerafdrukken. Geen kokend water; docent bepaalt de veilige werkwijze.','Korte video of fotoreeks met begin, handeling en resultaat.'],
['4 · Lopen met borden','20 minuten · bediening','Begin met één leeg bord en oefen rustig op een obstakelvrije route. Kijk vooruit en houd de rand schoon. Meer borden of gevulde borden pas na docentakkoord.','Korte video van oppakken, lopen en rustig neerzetten.']
].map(([name,time,work,proof])=>`<article class="card"><span class="kicker">${time}</span><h3>${name}</h3><p>${work}</p><p class="callout"><strong>Bewijs:</strong> ${proof}</p></article>`).join('')}</div><p class="smallprint">Wissel na elk station; geef de plek schoon door. Maak alleen herkenbare opnamen van personen met toestemming. Bewaar bewijs op de afgesproken schoollocatie.</p>`;
 if(isPeriod1)body=periodText(body);
 root.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><img class="school-logo" src="assets/images/maris-logo.png" alt="Maris College" width="120" height="60"><div class="brand-name">gastheerschap<small>MARIS COLLEGE</small></div></div><div class="side-label">Jouw keukenroute</div><nav class="nav" aria-label="Hoofdnavigatie">${NAV.map(x=>`<button class="nav-btn ${ui.view===x[0]?'is-on':''}" type="button" aria-current="${ui.view===x[0]?'page':'false'}" data-nav="${x[0]}"><i>${x[2]}</i><span>${x[1]}</span></button>`).join('')}</nav><a class="portal-switch portal-side portal-switch--teacher" href="${(isTeacher?'index.html':'docent.html')+(isPeriod1?'?periode=1':'?periode=2')}">${isTeacher?'← Leerlingenomgeving':'🍽️ Docentenomgeving'}</a><div class="side-foot">✦ <strong>${isPeriod1?'Een lunch met aandacht':'Een high tea met betekenis'}</strong><br>${isPeriod1?'Bereid samen een lunch voor jullie zelf en vier docenten.':'Leer, kook en ontvang de ouderen van Nolenshage.'}<div class="tiny">Datum eindopdracht: ${E(state.meta.eventDate||'volgt nog')}</div></div></aside><div class="main"><div class="mobile-bar"><label for="mobile-view-select">Ga naar</label><select id="mobile-view-select" aria-label="Kies een onderdeel">${NAV.map(x=>`<option value="${x[0]}" ${ui.view===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><a class="mobile-portal-link" href="${(isTeacher?'index.html':'docent.html')+(isPeriod1?'?periode=1':'?periode=2')}">${isTeacher?'Leerlingenomgeving':'Docentenomgeving'} ↗</a></div><header class="topbar"><div class="crumb"><img class="mobile-school-logo" src="assets/images/maris-logo.png" alt="Maris College" width="90" height="44">MARIS / GASTHEERSCHAP / <strong>${E(active[1])}</strong></div><div class="top-right"><a class="portal-switch portal-switch--top portal-switch--teacher" href="${(isTeacher?'index.html':'docent.html')+(isPeriod1?'?periode=1':'?periode=2')}" aria-label="${isTeacher?'Ga naar de leerlingenomgeving':'Ga naar de docentenomgeving'}">${isTeacher?'← Leerlingenomgeving':'🍽️ Docentenomgeving'}</a>${isTeacher?tag('Docent · lokale versie','gold'):tag('Leerling · lokale versie','green')}<button class="user-chip" type="button" data-act="choose-profile" title="Wissel leerling"> <span class="dot"></span>${E(state.active)} ▾</button></div></header><main id="main-content" tabindex="-1" class="content"><nav class="period-picker" aria-label="Kies de periode"><a class="period-button ${isPeriod1?'selected':''}" href="?periode=1#home" ${isPeriod1?'aria-current="page"':''}>Periode 1 <small>3 bijeenkomsten · docentenlunch</small></a><a class="period-button ${!isPeriod1?'selected':''}" href="?periode=2#home" ${!isPeriod1?'aria-current="page"':''}>Periode 2 <small>8 bijeenkomsten · high tea</small></a></nav><nav class="design-picker" aria-label="Kies je vormgeving"><span class="meeting-nav-label">Kies je stijl</span><div class="meeting-buttons">${[['1','Fris mint'],['2','Zonnig perzik'],['3','Helder blauw']].map(([id,name])=>`<button type="button" class="design-button" data-design="${id}" aria-pressed="${document.body.dataset.design===id}" title="${name}">Stijl ${id}</button>`).join('')}</div></nav><nav class="meeting-nav" aria-label="Kies een bijeenkomst"><span class="meeting-nav-label">Bijeenkomsten</span><div class="meeting-buttons">${DATA.sessions.map(s=>`<button type="button" class="meeting-button ${ui.view==='programme'&&ui.lesson===s.id?'selected':''}" data-act="open-lesson" data-id="${s.id}" aria-label="Bijeenkomst ${s.id}: ${E(s.title)}" ${ui.view==='programme'&&ui.lesson===s.id?'aria-current="step"':''}>${s.id}</button>`).join('')}</div></nav>${body}<div class="footer-note">© Lesomgeving voor Maris College Bohemen · Concept op basis van aangeleverde lessen en HBR P1-samenvatting. <strong>De voortgang wordt alleen in deze browser opgeslagen</strong>; er is nog geen account, centrale opslag of beveiligde docentlogin. Gebruik leerlingcodes en exporteer regelmatig een back-up. Theorie en rubric zijn eigen lesuitwerkingen; controleer de SE-afspraken en veiligheid voor invoering.</div>${ui.print?`<section class="print-only">${renderPrintable()}</section>`:''}</main></div></div>`;
 }
function periodText(html){return html.replaceAll('Acht bijeenkomsten','Drie bijeenkomsten').replaceAll('acht bijeenkomsten','drie bijeenkomsten').replaceAll('achtbijeenkomstenprogramma','driebijeenkomstenprogramma').replaceAll('De acht aftekenlijsten','De drie aftekenlijsten').replaceAll('Zes kookmomenten: twee uit je bestaande lessen, één eigen recept met instructievideo en drie nieuwe high-teagerechten. Minimaal vijf momenten worden volledig beoordeeld.','Eén lunchgerecht, drie oefen- en uitvoeringsmomenten. Werk in carrouselvorm aan bereiding en bediening.').replaceAll('minimaal vijf','drie').replaceAll('minimaal 5','3').replaceAll('vijf volledige','drie volledige').replaceAll('minstens vijf','drie').replaceAll('vijf kookmomenten','drie kookmomenten').replaceAll('vijf gemaakte gerechten','drie bereidingen').replaceAll('vijf compleet','drie compleet').replaceAll('5 volledig','3 volledig').replaceAll('high tea','docentenlunch').replaceAll('High tea','Docentenlunch').replaceAll('ouderen van Nolenshage','vier docenten').replaceAll('ouderen van vier docenten','vier docenten').replaceAll('Nolenshage','de school').replaceAll('Van koken en klantvriendelijkheid tot een echte docentenlunch.','Van de lunchcarrousel tot een echte docentenlunch.').replaceAll('Datum volgt','Datum bijeenkomst 3 nog bevestigen');}
function renderPeriodHome(){return title('Periode 1 · drie bijeenkomsten','Samen een docentenlunch verzorgen','Voor jullie zelf en vier docenten. In bijeenkomst 3 ontvangen jullie de gasten tijdens de grote pauze, van 11.30 tot 12.00 uur. De lunchdatum wordt nog bevestigd.')+`<div class="card cream"><h2>Volgende les: lunchlab in carrousel</h2><p><strong>Ook op het programma:</strong> we gaan langs KC Aquamarijn voor de extra formulieren en de Kapla. De docent spreekt af wanneer we gaan.</p><p>Vier stations: clubsandwich bereiden, tafel indekken, poleren en lopen met borden. Leg iedere vaardigheid vast met een foto of korte video. Werk daarna aan jullie tijdsplanning, uitnodiging, menukaart en materialenlijst.</p><p><strong>Gerecht:</strong> clubsandwich met volledig gegaarde kip of vegetarisch beleg. Liever eenvoudiger? Kies na overleg een luxe broodje gezond.</p><div class="button-row">${button('Open bijeenkomst 1','open-lesson','', 'data-id="1"')}${button('Maak uitnodiging en menu','go-hightea','ghost')}</div></div><div class="section-head"><h2>Jullie route in drie stappen</h2></div><div class="grid three">${DATA.sessions.map(x=>`<button class="item-card" data-act="open-lesson" data-id="${x.id}"><span class="kicker">Bijeenkomst ${x.id}</span><h3>${E(x.title)}</h3><p class="muted">${E(x.subtitle)}</p></button>`).join('')}</div><div class="section-head"><h2>Voorbereiden voor leerlingen + vier docenten</h2></div><div class="grid two"><div class="card"><h3>Wat moet er klaarliggen?</h3><ul class="detail-list"><li>Porties: aantal leerlingen + 4 docenten. Reserve apart afspreken.</li><li>Brood, beleg, groenten, saus en dranken; allergenen en koeling controleren.</li><li>Borden, bestek, glazen, servetten en voldoende zitplaatsen.</li><li>Schone poleerdoeken, afwasmiddelen, serveermaterialen en vrije looproute.</li><li>Uitnodiging, menukaart, taakverdeling en tijdsplanning laten goedkeuren.</li></ul></div><div class="card"><h3>Bewijs voor je portfolio</h3><p>Maak een foto van het gerecht en de ingedekte tafel. Film kort het poleren en veilig lopen met borden, of gebruik een fotoreeks als filmen niet kan.</p><p class="smallprint">Bewaar bestanden op de afgesproken schoollocatie. De app uploadt geen foto’s of video’s. Film geen herkenbare klasgenoten of docenten zonder toestemming.</p><p class="callout">Periode 1 en Periode 2 bewaren hun voortgang apart in deze browser.</p></div></div>`;}
function renderPeriodGuide(){return title('Docent · periode 1','Draaiboek docentenlunch','Drie bijeenkomsten; vier docenten en alle deelnemende leerlingen eten mee. De lunchdatum en het lokaal blijven nog te bevestigen.')+DATA.sessions.map(s=>`<section class="card" style="margin-bottom:20px"><h2>${s.id}. ${E(s.title)}</h2><p>${E(s.goal)}</p><ol class="detail-list">${s.blocks.map(b=>`<li><strong>${E(b[0])} · ${E(b[1])}</strong>: ${E(b[2])}</li>`).join('')}</ol></section>`).join('')+`<div class="callout">Carrousel: vier teams, ieder station 20 minuten, drie wissels van 3 minuten. Begeleid snijden, poleren en dragen; begin met lege borden. Gebruik geen kokend water bij het poleren. Bewijs veilig op school opslaan. De rubric gebruikt dezelfde weging, met drie volledig beoordeelde bereidingen in deze periode; bevestig dit als schoolafspraak.</div>`;}
function renderHome(){const prog=doneTasks(), last=DATA.sessions.filter(s=>s.tasks.some(t=>P().checks[`${s.id}_${t[0]}`])).at(-1);let best=P().quizHistory.filter(x=>['h1','h2','h4','h6','all'].includes(x.filter)).sort((a,b)=>b.percentage-a.percentage)[0];
return `<section class="hero"><div class="hero-copy"><div class="eyebrow">JOUW KEUKEN · JOUW VERHAAL</div><h1>Alles begint met <em>gastvrijheid.</em></h1><p>In acht bijeenkomsten ga je van eerste mise-en-place naar een echte high tea voor de ouderen van Nolenshage.</p><div class="button-row">${button('Bekijk de 8 bijeenkomsten →','go-programme','')} ${button('Oefen voor je SE','go-quiz','ghost')}</div></div><img src="assets/images/high-tea.webp" alt="Sfeervolle high tea met thee, scones, sandwiches en kleine hartige hapjes" width="1536" height="1024" fetchpriority="high"></section>
<div class="section-head"><h2>Jouw voortgang</h2><p class="muted">Iedere opdracht telt mee in je leerproces</p></div><div class="grid four"><div class="card stat"><span class="label">Bijeenkomsten</span><strong class="value">8</strong><span class="sub">van start tot high tea</span></div><div class="card stat"><span class="label">Afgevinkte taken</span><strong class="value">${prog.done}<small style="color:#819684;font-size:17px"> / ${prog.total}</small></strong><div class="metric-bar"><div style="width:${prog.pct}%"></div></div></div><div class="card stat"><span class="label">Kookmomenten</span><strong class="value">6</strong><span class="sub">minimaal vijf beoordeeld</span></div><div class="card stat"><span class="label">Beste oefentoets</span><strong class="value">${best?best.percentage+'%':'—'}</strong><span class="sub">staat los van praktijkcijfer</span></div></div>
<div class="section-head"><h2>Kies jouw volgende stap</h2></div><div class="grid three"><button type="button" class="item-card" data-nav="programme"><div class="iconcard">📋</div><div class="title">Mijn bijeenkomsten</div><div class="desc">Programma, opdrachten en checklists per les.</div><p class="link-arrow">↗</p></button><button type="button" class="item-card" data-nav="theory"><div class="iconcard">📚</div><div class="title">Theorie zonder boek</div><div class="desc">Leer in je eigen tempo, met uitleg en praktijkvoorbeelden.</div><p class="link-arrow">↗</p></button><button type="button" class="item-card" data-nav="hightea"><div class="iconcard">🫖</div><div class="title">High tea Nolenshage</div><div class="desc">Maak uitnodiging, menukaart, budget en planning.</div><p class="link-arrow">↗</p></button></div>
<div class="section-head"><h2>Zelf oefenen en nakijken</h2></div><div class="card"><div class="flex-between"><div><h3>Interactieve lessen bij elke bijeenkomst</h3><p class="muted tiny">Beantwoord 5 situaties per les, klik op Nakijken en ontvang direct feedback en uitleg. Je score telt niet mee voor je praktijkcijfer.</p></div>${button('Start een interactieve les →','go-interactive','')}</div></div><div class="section-head"><h2>De route naar Nolenshage</h2><button class="btn small ghost" data-nav="programme">Bekijk alle lessen →</button></div><div class="grid two">${DATA.sessions.slice(0,4).map(s=>`<button class="row-lesson" data-act="open-lesson" data-id="${s.id}"><div class="row-num">${s.id<10?'0'+s.id:s.id}</div><div><strong>${E(s.title)}</strong><small>${E(s.subtitle)}</small></div><span class="link-arrow">↗</span></button>`).join('')}</div>
<div class="section-head"><h2>Waar werk je naartoe?</h2></div><div class="card cream"><div class="kicker" style="color:#607552">HET EINDPROJECT</div><h2 style="font-family:Georgia,serif;font-size:30px;margin-top:8px">Een warme high tea voor Nolenshage</h2><p class="muted">Jullie verzorgen de uitnodiging, de menukaart, de hapjes, de tafels en het gastvrije ontvangst. De datum en praktische afspraken worden later door de docent ingevuld.</p><div class="button-row">${tag('Datum volgt','gold')}${tag('Echte gasten','green')}<button type="button" class="btn dark" data-nav="hightea">Ontdek het eindproject →</button></div></div>`;}
function renderProgramme(){let s=lesson(), done=s.tasks.filter(x=>P().checks[`${s.id}_${x[0]}`]).length;let sidebar=DATA.sessions.map(x=>{let n=x.tasks.filter(t=>P().checks[`${x.id}_${t[0]}`]).length;return `<button type="button" class="row-lesson ${x.id===s.id?'selected':''}" data-act="open-lesson" data-id="${x.id}" style="${x.id===s.id?'border-color:#afcda6;background:#e2f4e7;':''}"><div class="row-num">${String(x.id).padStart(2,'0')}</div><div><strong>${E(x.title)}</strong><small>${n}/${x.tasks.length} taken · ${E(x.type)}</small></div><span class="link-arrow">${x.id===s.id?'●':'↗'}</span></button>`}).join('');
return title('Het lesprogramma','Acht bijeenkomsten','Van koken en klantvriendelijkheid tot een echte high tea. De tijdvakken zijn een voorstel van circa 150 minuten per les, en worden door de docent aangepast aan het rooster.')+`<div class="split"><div><div class="card" style="margin-bottom:17px"><div class="flex-between"><div><span class="kicker">Bijeenkomst ${s.id} · ${E(s.type)}</span><h2 style="margin:10px 0 8px">${E(s.title)}</h2><p class="muted">${E(s.subtitle)}</p></div><span style="font-size:42px">${s.id===8?'🫖':'🍽️'}</span></div><div class="callout">🎯 <b>Leerdoel:</b> ${E(s.goal)}</div><div class="section-head"><h3>Lesverloop</h3><span class="pill">Indicatieve tijd</span></div><div class="timeline">${s.blocks.map(b=>`<div class="time-step"><span class="time">${E(b[1])}</span><div class="time-line"><strong>${E(b[0])}</strong><p>${E(b[2])}</p></div></div>`).join('')}</div><div class="button-row" style="margin-top:15px">${s.cook?button('Bekijk het recept →','recipe-session','ghost') :button('Naar de high tea →','go-hightea','ghost')} ${button('Open de leerstof →','theory-session','ghost')} ${button('Interactieve les + zelf nakijken →','interactive-session','')}</div></div>
<div class="card"><div class="flex-between"><div><h2 style="margin:0 0 6px">Mijn aftekenlijst</h2><p class="muted tiny" style="margin:0">Vink zelf af wat je gedaan hebt. De docent beoordeelt praktijkvaardigheden apart in de rubric.</p></div>${tag(`${done}/${s.tasks.length} klaar`,'green')}</div><div class="metric-bar"><div style="width:${percent(done,s.tasks.length)}%"></div></div><div class="check-group" style="margin-top:18px">${s.tasks.map(t=>{let key=`${s.id}_${t[0]}`, checked=!!P().checks[key];return `<label class="task ${checked?'done':''}"><input type="checkbox" data-check="${E(key)}" ${checked?'checked':''}><span><strong>${E(t[1])}</strong><small>${E(t[2])}</small></span></label>`}).join('')}</div><div class="field"><label for="lesson-note">Mijn lesnotities en feedback</label><textarea id="lesson-note" data-scope="lessonNote" data-key="${s.id}" placeholder="Wat ging goed? Wat ga je de volgende keer beter doen?">${E(P().lessonNotes[s.id]||'')}</textarea></div></div></div><div><div class="card"><h3>Alle bijeenkomsten</h3><div class="list-flow">${sidebar}</div></div><div class="card" style="margin-top:17px"><div class="kicker">THEORIE IN DEZE LES</div><div class="pills" style="margin-top:12px">${s.theory.map(id=>tag(`H${cData(id).n} ${cData(id).se?'· SE':''}`,cData(id).se?'gold':'green')).join('')}</div><p class="smallprint" style="margin-top:12px">Theoriehoofdstukken 1, 2, 4 en 6 horen bij het SE. Hoofdstuk 3, 5 en de veiligheidsstof uit 7 ondersteunen het praktijkgedeelte.</p></div></div></div>`;}

function interactionSource(n){return DATA.lessonInteractions.find(x=>x.id===Number(n))||DATA.lessonInteractions[0];}
function getCheckedLesson(n){return P().lessonChecks?.[n]||null;}
function renderInteractive(){let sid=ui.interactiveLesson,s=DATA.sessions.find(x=>x.id===sid),unit=interactionSource(sid),previous=getCheckedLesson(sid);
 let answers=ui.interactiveAnswers;
 return title('Oefen / denk / controleer','Interactieve lessen','Werk per bijeenkomst aan vijf herkenbare praktijksituaties. Kies een antwoord en kijk alles zelf na. De app bewaart je laatste score; de docent beoordeelt het praktische werk apart.')+
 `<div class="tabs">${DATA.sessions.map(x=>`<button type="button" class="tab ${x.id===sid?'active':''}" data-act="interactive-lesson" data-id="${x.id}">Les ${x.id}${getCheckedLesson(x.id)?' ✓':''}</button>`).join('')}</div>
 <div class="card lesson-intro"><div class="flex-between"><div><div class="kicker">BIJEENKOMST ${sid} · ZELFTOETS</div><h2 style="margin:9px 0">${E(s.title)}</h2><p>${E(unit.intro)}</p></div><span class="interact-icon">${sid===8?'🫖':'👩‍🍳'}</span></div><div class="lesson-note"><strong>Stel je voor</strong><br>${E(unit.scenario)}</div>
 <div class="pills">${tag('5 vragen · geen tijdslimiet','green')}${tag('Meteen uitleg na nakijken')}${previous?tag('Eerder: '+previous.score+'/5 goed','gold'):''}</div></div>
 <div class="selfcheck-list">${unit.questions.map((q,i)=>{let given=answers[i],correct=given===q[2],checked=ui.interactiveChecked;
 return `<article class="card self-question"><div class="flex-between"><span class="kicker">VRAAG ${i+1} VAN ${unit.questions.length}</span>${checked?tag(correct?'Goed':'Bekijk uitleg',correct?'green':'gold'):tag('Kies één antwoord')}</div><h3>${E(q[0])}</h3><div class="self-options">${q[1].map((choice,j)=>`<label class="self-option ${checked&&j===q[2]?'is-right':''} ${checked&&given===j&&j!==q[2]?'is-wrong':''}"><input type="radio" name="lesson-q-${i}" data-lesson-answer="${i}" value="${j}" ${given===j?'checked':''} ${checked?'disabled':''}><span>${E(choice)}</span></label>`).join('')}</div>${checked?`<div class="answer-explanation ${correct?'':'error'}"><strong>${correct?'✓ Goed gekozen':'✕ Dit was het juiste antwoord: '+E(q[1][q[2]])}</strong><p style="margin:8px 0 0">${E(q[3])}</p></div>`:''}</article>`;}).join('')}</div>
 <div class="card self-footer"><div><h3>${ui.interactiveChecked?'Jouw uitslag':'Klaar om na te kijken?'}</h3><p class="muted tiny">${ui.interactiveChecked?'De uitleg staat bij alle vragen. Verbeter je kennis met de theorie of probeer opnieuw.':'Beantwoord alle vragen. Je hoeft niet alles goed te hebben: je leert juist van de feedback.'}</p>${ui.interactiveChecked?`<div class="self-result">${unit.questions.filter((q,i)=>answers[i]===q[2]).length} / ${unit.questions.length} goed <span>· ${Math.round(unit.questions.filter((q,i)=>answers[i]===q[2]).length/unit.questions.length*100)}%</span></div>`:''}</div><div class="button-row">${ui.interactiveChecked?`${button('Opnieuw oefenen','retry-interactive','ghost')} ${button('Naar de leschecklist →','return-programme','')}`:button('Kijk mijn antwoorden na →','check-interactive','')}</div></div>
 <div class="callout" style="margin-top:17px"><b>Let op:</b> deze zelftoets controleert kennis. Een leerlingvinkje of zelfs 5/5 goed is geen bewijs dat koken of serveren correct is uitgevoerd. De docent blijft verantwoordelijk voor de praktijkrubric.</div>`;
}
function renderDocuments(){if(!isTeacher)return renderHome();let docs=window.GH_DOCUMENTS||[],cat=ui.documentsFilter,filtered=cat==='all'?docs:docs.filter(d=>d.category===cat),name={theorie:'Theorie',beoordeling:'Beoordeling',presentatie:'Presentaties',handleiding:'Handleidingen',bron:'Bronnen'};
 let bytes=x=>x>1048576?(x/1048576).toFixed(1).replace('.',',')+' MB':Math.max(1,Math.round(x/1024))+' KB';
 return title('Docent · alles op één plek','Documentenbibliotheek','Een bibliotheek van lespresentaties, werkbladen en handleidingen. De originele bestanden zijn lokaal bewaard. Downloads worden pas openbaar aangeboden nadat de school de verspreidingsrechten heeft bevestigd.')+
 `<div class="grid three"><div class="card stat"><span class="label">Bronbestanden en handleidingen</span><strong class="value">${docs.length}</strong><span class="sub">Alles in het complete ZIP-pakket</span></div><div class="card stat"><span class="label">Lespresentaties</span><strong class="value">3</strong><span class="sub">Met directe PDF-preview</span></div><div class="card stat"><span class="label">Toegang</span><strong class="value" style="font-size:26px">Open</strong><span class="sub">Geen wachtwoord of inlog</span></div></div>
 <div class="callout warn" style="margin:20px 0"><strong>Docentendeel zonder wachtwoord</strong><br>Op jouw verzoek is deze omgeving vrij toegankelijk. Deel de link dus alleen bewust: als je de hele site online zet, zijn de bronbestanden en rubricfuncties publiek toegankelijk. Beoordelingen blijven lokaal in de browser, niet op een schoolserver.</div>
 <div class="tabs">${[['all','Alle documenten'],...Object.entries(name)].map(([id,title])=>`<button class="tab ${cat===id?'active':''}" data-act="documents-filter" data-id="${id}">${E(title)}</button>`).join('')}</div>
 <div class="docs-grid">${filtered.map(d=>{let icon=d.filename.endsWith('.pptx')?'▤':d.filename.endsWith('.docx')?'▣':d.filename.endsWith('.pdf')?'▥':'▧';return `<article class="card doc-card"><div class="flex-between"><span class="doc-icon">${icon}</span>${tag(name[d.category]||d.category,'green')}</div><h3>${E(d.title)}</h3><p class="muted tiny">${E(d.description)}</p><p class="smallprint">${E(d.source)} · ${bytes(d.size)}</p><div class="doc-actions">${window.GH_DOCUMENT_ACCESS&&d.preview?`<a class="btn ghost small" data-file-path="${E(d.preview)}" data-file-action="open" href="${E(d.preview)}" target="_blank" rel="noopener">Bekijk ${d.preview.endsWith('.png')?'afbeelding':'PDF'} ↗</a>`:''}${window.GH_DOCUMENT_ACCESS?`<a class="btn dark small" data-file-path="${E(d.href)}" data-file-action="download" href="${E(d.href)}" download="${E(d.source)}">Download origineel ↓</a>`:`<span class="smallprint">Lokaal bewaard · publicatierechten nog te controleren</span>`}</div></article>`;}).join('')}</div><div class="callout" style="margin-top:18px">De originele PowerPoints en PDF-leesversies blijven lokaal bewaard voor gebruik door de school. Ook de HBR-samenvatting en de oorspronkelijke rubrics zijn lokaal behouden. Beoordelingsmodel van de app is een nieuw voorstel; de originele formulieren zijn afzonderlijk bewaard.</div>`;
}

function renderTheory(){let c=cData(ui.chapter);return title('Kennis / begrijpen / toepassen','Alle leerstof bij de hand','Eigen uitleg bij alle belangrijke onderwerpen uit de aangeleverde HBR P1-samenvatting. Hoofdstuk 1, 2, 4 en 6 zijn de afgesproken SE-stof; hoofdstuk 3 en 5 en de aanvullende keukenmodule zijn praktijkondersteuning.')+
`<div class="tabs">${DATA.chapters.map(x=>`<button class="tab ${x.id===ui.chapter?'active':''}" type="button" data-act="chapter" data-id="${x.id}">H${x.n} ${x.se?'★':''}</button>`).join('')}</div><div class="split"><div class="card"><div class="flex-between"><div><span class="kicker">HOOFDSTUK ${c.n} ${c.se?'· SE-STOF':'· PRAKTIJK'}</span><h2 style="margin:10px 0">${E(c.title)}</h2><p class="muted">${E(c.subtitle)}</p></div><span style="font-size:38px">${c.se?'📘':'🧑‍🍳'}</span></div><div class="muted-box">💡 Lees de uitleg per paragraaf, probeer het voorbeeld en onthoud de kernzin. Je kunt de hoofdstukken zelfstandig doornemen zonder het theorieboek erbij te pakken.</div><div style="margin-top:24px">${c.topics.map((t,i)=>`<details class="topic" ${i===0?'open':''}><summary><strong><span style="color:#92581f;margin-right:10px">${E(t[0])}</span>${E(t[1])}</strong><i>＋</i></summary><p>${E(t[2])}</p><div class="lesson-note"><b>Voorbeeld uit de praktijk</b><br>${E(t[3])}</div><div class="lesson-note"><b>Onthouden</b><br>${E(t[4])}</div></details>`).join('')}</div><div class="button-row" style="margin-top:20px"><button class="btn" data-act="quiz-chapter" data-id="${c.id}">Oefen vragen over H${c.n} →</button></div></div><div><div class="card cream"><div class="kicker" style="color:#59754e">SNELLE LEERROUTE</div><h3 style="font-family:Georgia,serif;font-size:23px;margin:12px 0">4 hoofdstukken voor het SE</h3>${['h1','h2','h4','h6'].map(id=>{let x=cData(id);return `<button type="button" class="row-lesson" style="background:#f7f1e6;color:#263b2a;border:1px solid #d7d3c6;margin-bottom:8px" data-act="chapter" data-id="${id}"><span class="row-num" style="background:#dce7d7;color:#314a33">${x.n}</span><div><strong>${E(x.title)}</strong><small style="color:#657668">${x.topics.length} paragrafen</small></div>↗</button>`}).join('')}</div><div class="card" style="margin-top:17px"><h3>Zo leer je voor het SE</h3><ol class="detail-list"><li>Lees ieder onderwerp.</li><li>Leg kernbegrippen in eigen woorden uit.</li><li>Maak de vragen per hoofdstuk.</li><li>Herhaal alle vier hoofdstukken met de gemengde toets.</li></ol>${button('Start gemengd oefenexamen','go-quiz','ghost')}</div></div></div>`;}
function quizMake(){let bank=DATA.quiz.filter(q=>ui.quizFilter==='all'?['h1','h2','h4','h6'].includes(q[0]):q[0]===ui.quizFilter);let shuffle=x=>{let y=[...x];for(let i=y.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[y[i],y[j]]=[y[j],y[i]]}return y;};
let selected=[];if(ui.quizFilter==='all'){const groups=['h1','h2','h4','h6'];let per=Math.floor(ui.quizCount/4);for(const id of groups)selected.push(...shuffle(bank.filter(q=>q[0]===id)).slice(0,per));let left=shuffle(bank.filter(x=>!selected.includes(x)));selected.push(...left.slice(0,ui.quizCount-selected.length));}else selected=shuffle(bank).slice(0,ui.quizCount);
ui.quiz={items:shuffle(selected).map(q=>{let opts=shuffle(q[2].map((t,i)=>({t,correct:i===q[3]})));return{chapter:q[0],q:q[1],options:opts,explain:q[4]};}),index:0,answered:null,points:0,finished:false};}
function renderQuiz(){let all=DATA.quiz.filter(x=>['h1','h2','h4','h6'].includes(x[0]));if(!ui.quiz){return title('Maak jezelf toetsklaar','SE-oefentrainer','Train alle vier de SE-hoofdstukken of kies één hoofdstuk. De antwoorden staan bewust door elkaar; na iedere vraag krijg je uitleg.')+`<div class="split"><div class="card"><h2>Kies je oefentoets</h2><div class="field"><label>Welke leerstof?</label><select data-uivalue="quizFilter" class="select-light"><option value="all" ${ui.quizFilter==='all'?'selected':''}>Gemengd · H1, H2, H4 en H6</option>${DATA.chapters.filter(x=>x.se).map(x=>`<option value="${x.id}" ${ui.quizFilter===x.id?'selected':''}>Hoofdstuk ${x.n} · ${E(x.title)}</option>`).join('')}</select></div><div class="field"><label>Aantal vragen</label><select data-uivalue="quizCount" class="select-light">${[10,12,20,30,50].map(n=>`<option value="${n}" ${ui.quizCount===n?'selected':''}>${n} vragen</option>`).join('')}</select></div><div class="callout">${all.length} oefenvragen zijn beschikbaar voor de SE-stof. Vragen en uitlegregels zijn nieuw geschreven bij de aangeleverde samenvatting.</div><div style="margin-top:18px">${button('Start de oefentoets →','start-quiz','')}</div></div><div class="card cream"><div style="font-size:42px">🎓</div><h2 style="font-family:Georgia,serif;margin-top:12px">Oefenen mag fout gaan</h2><p>Je ziet meteen waarom een antwoord goed of fout is. Je score wordt opgeslagen op dit apparaat, maar telt niet mee voor het praktijkcijfer.</p><span class="pill" style="color:#536852;border-color:#9ead9b">SE en praktijk blijven gescheiden</span></div></div>`;}
let qz=ui.quiz;if(qz.finished){let pct=percent(qz.points,qz.items.length);return title('Goed geoefend','Je toets is afgerond','Bekijk je resultaat, herhaal de uitleg of probeer een nieuwe selectie.')+`<div class="card" style="max-width:750px;text-align:center;padding:40px"><div class="kicker">JOUW SCORE</div><div class="score-hero">${pct}%</div><h2>${qz.points} van ${qz.items.length} goed</h2><div class="metric-bar"><div style="width:${pct}%"></div></div><p class="muted">${pct>=80?'Sterk werk! Blijf herhalen.':pct>=60?'Je bent op weg. Herhaal de lastige begrippen.':'Lees de theorie opnieuw en probeer nog eens.'}</p><div class="button-row" style="justify-content:center">${button('Nieuwe oefentoets','restart-quiz','')}${button('Terug naar leerstof','go-theory','ghost')}</div></div>`;}
let q=qz.items[qz.index],ans=qz.answered;
return title('SE-training',`Vraag ${qz.index+1} van ${qz.items.length}`,'Lees rustig, kies je antwoord en bekijk de uitleg.')+`<div class="card" style="max-width:850px"><div class="quiz-progress"><span>${E(cData(q.chapter).title)}</span><strong>${qz.points} goed</strong></div><div class="metric-bar"><div style="width:${percent(qz.index,qz.items.length)}%"></div></div><h2 class="question">${E(q.q)}</h2>${q.options.map((o,i)=>`<button type="button" class="option ${ans!==null?(o.correct?'correct':i===ans?'wrong':''):''}" data-act="quiz-answer" data-id="${i}" ${ans!==null?'disabled':''}><span class="letter">${'ABC'[i]}</span>${E(o.t)}${ans!==null&&o.correct?'<span style="margin-left:auto">✓</span>':''}</button>`).join('')}${ans!==null?`<div class="answer-explanation ${q.options[ans].correct?'':'error'}"><strong>${q.options[ans].correct?'✓ Goed gedaan!':'↪ Dit is de uitleg'}</strong><p style="margin:7px 0 0">${E(q.explain)}</p></div><div class="button-row" style="margin-top:18px">${button(qz.index===qz.items.length-1?'Bekijk mijn score →':'Volgende vraag →','quiz-next','')}</div>`:''}</div>`;}
function renderKitchen(){let r=recipe();return title('Handen wassen · schort om','Het keukenlab','Zes kookmomenten: twee uit je bestaande lessen, één eigen recept met instructievideo en drie nieuwe high-teagerechten. Minimaal vijf momenten worden volledig beoordeeld.')+`<div class="tabs">${DATA.recipes.map(x=>`<button type="button" class="tab ${x.id===ui.recipe?'active':''}" data-act="recipe" data-id="${x.id}">Les ${x.meeting}</button>`).join('')}</div><div class="split"><div class="card">${r.image?`<img class="recipe-photo" src="${E(r.image)}" alt="Afbeelding uit aangeleverde lespresentatie van ${E(r.title)}">`:`<img class="recipe-photo" src="${r.id==='scones'?'assets/images/scones.webp':'assets/images/high-tea.webp'}" alt="${r.id==='scones'?'Scones met jam en thee als serveersuggestie':'High tea als inspiratie voor de gerechten'}" width="1536" height="1024" loading="lazy"><p class="image-caption">Sfeerbeeld · geen exacte weergave van dit recept</p>`}<div class="kicker">KOOKMOMENT ${r.meeting}</div><h2 style="font-family:Georgia,serif;font-size:30px;margin:10px 0">${E(r.title)}</h2><div class="pills">${tag(r.time)}${tag(r.makes,'green')}</div><p class="muted tiny" style="margin-top:14px">${E(r.note)}</p><div class="callout"><b>Allergenencheck:</b> ${E(r.allergens)} De docent controleert verpakkingen, voedselveiligheid en eventuele alternatieven.</div><div class="section-head"><h3>Bereidingsstappen</h3></div><ol class="recipe-steps">${r.steps.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="button-row no-print">${button('Ga naar deze les','go-recipe-lesson','ghost')}${button('Print dit recept','print-recipe','ghost')}</div></div><div><div class="card"><div class="kicker">MISE-EN-PLACE</div><h3 style="margin-top:12px">Wat heb je nodig?</h3><div class="recipe-ingredients">${r.ingredients.map((x,i)=>`<label><input type="checkbox" aria-label="Ingrediënt ${E(x)}">${E(x)}</label>`).join('')}</div><p class="smallprint">Deze materiaalcheck is tijdelijk. Je aftekenlijst staat bij de bijeenkomst.</p></div><div class="card" style="margin-top:17px"><h3>De vijf vaste keukenstappen</h3><ol class="detail-list"><li>Persoonlijke hygiëne</li><li>Voorbereiding en mise-en-place</li><li>Uitvoering en techniek</li><li>Afwassen</li><li>Werkplekcontrole</li></ol><p class="smallprint">Afgeleid van de drie aangeleverde lespresentaties.</p></div><div class="card" style="margin-top:17px"><h3>Kleur snijplanken in de les</h3><div class="pills">${[['🟨','Gevogelte'],['🟦','Vis'],['🟩','Groente/fruit'],['🟫','Gebraden vlees'],['🟥','Rauw vlees'],['⬜','Kaas/brood']].map(x=>tag(x[0]+' '+x[1])).join('')}</div><p class="smallprint">Volg altijd de actuele werkinstructies van de schoolkeuken.</p></div></div></div>`;}
function renderTable(){const feedback=ui.tableFeedback;return title('Carrousel / bediening','Tafel indekken','Een goede high tea begint met een nette tafel. Oefen hieronder waar de materialen bij een eenvoudig couvert horen en laat je docent de echte tafel beoordelen.')+`<div class="split"><div class="card"><h2>De high-teatafel</h2><p class="muted">Kijk naar de voorbeeldtafel en kies voor elk materiaal de juiste plaats.</p><div class="table-game"><div class="plate-board"><span class="glass">◉</span><span class="fork">♆</span><div class="plate"></div><span class="knife">│</span><span class="napkin">▱</span></div><div><div class="check-group">${DATA.tableExercise.map((x,i)=>`<div class="field" style="margin:0"><label>${E(x.item)}</label><select class="select-light" style="width:100%" data-table="${i}"><option value="">Kies een plek…</option>${[['links','Links van het bord'],['rechts','Rechts, snijkant naar binnen'],['rechtsboven','Rechtsboven het bord'],['opbord','Op of naast het bord'],['rechtskop','Rechts bij de gast']].map(o=>`<option value="${o[0]}" ${ui.tableAnswers[i]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></div>`).join('')}</div><div style="margin-top:16px">${button('Controleer mijn tafel','check-table','')}</div></div>${feedback?`<div class="summary-score" style="margin-top:17px"><strong>${feedback.ok} van ${feedback.total} correct</strong><p style="margin:8px 0 0">${DATA.tableExercise.map((x,i)=>`${ui.tableAnswers[i]===x.correct?'✓':'✕'} ${E(x.why)}`).join('<br>')}</p></div>`:''}</div><div class="callout" style="margin-top:16px">⚠ Dit is een vereenvoudigde oefenopstelling. In de praktijk wordt de tafel afgestemd op het menu, servies, comfort en eventuele mobiliteitshulpmiddelen. De docent beoordeelt de echte opstelling met de rubric.</div></div><div><div class="card"><h3>Praktijkcheck tafel indekken</h3><div class="check-group">${['Tafellaken of placemat schoon en recht','Borden schoon en op gelijke afstand','Bestek passend bij het menu','Glaswerk op de juiste plek','Servetten netjes','Looproute rondom de tafel veilig','Voldoende ruimte voor ouderen en hulpmiddelen'].map(x=>`<div class="task"><span>✓</span><strong>${E(x)}</strong></div>`).join('')}</div></div><div class="card" style="margin-top:17px"><h3>Ook oefenen in de carrousel</h3><div class="pills">${tag('Poleren')}${tag('Borden dragen')}${tag('Servetten vouwen')}${tag('Thee schenken')}${tag('Gasten ontvangen')}${tag('Debarrasseren')}</div></div></div></div>`;}
function eventInfo(){const d=state.meta;return{date:d.eventDate||'Datum volgt',time:d.eventTime||'Tijd volgt',place:d.eventPlace||'Locatie wordt bevestigd',guests:d.guestCount||'Aantal gasten volgt'};}
function renderHighTea(){let ev=eventInfo(),p=P(),i=p.invitation,m=p.menu;let plan=p.highteaPlan||(p.highteaPlan={role:'',notes:'',budget:[]});let budgetTotal=(plan.budget||[]).reduce((a,x)=>a+(Number(x.qty)||0)*(Number(x.price)||0),0);let guestN=isPeriod1&&Number.isInteger(plan.studentCount)?plan.studentCount+4:Number(state.meta.guestCount);let edit=(scope,key,label,val,type='input')=>`<div class="field"><label>${E(label)}</label>${type==='textarea'?`<textarea data-scope="${scope}" data-key="${key}">${E(val||'')}</textarea>`:`<input data-scope="${scope}" data-key="${key}" value="${E(val||'')}" />`}</div>`;
return (isPeriod1?`<div class="card" style="margin-bottom:20px"><h2>Aantallen en materialen</h2><label for="lunch-students">Aantal leerlingen dat mee-eet</label><input id="lunch-students" type="number" class="select-light" min="0" max="100" step="1" data-lunch-count value="${E(plan.studentCount??'')}"><p>Te plannen porties: <strong>${Number.isInteger(plan.studentCount)?plan.studentCount+4:'vul het aantal leerlingen in'}</strong> · leerlingen + vier docenten. Reserve en dieetporties apart met de docent afspreken.</p><p class="smallprint">Tel voor iedereen een bord, glas, bestek en servet. Regel snijplanken, messen, serveertangen, schone poleerdoeken, afwasmiddelen en gekoelde opslag.</p></div>`:'')+title('Eindopdracht / Nolenshage','Een high tea met aandacht','Samen organiseren jullie de uitnodiging, menukaart, producten en bediening voor ouderen van Nolenshage. De daadwerkelijke datum en locatie zijn nog niet bevestigd.')+
`<div class="card cream" style="margin-bottom:20px"><div class="grid four">${[['Datum',ev.date],['Tijd',ev.time],['Locatie',ev.place],['Gasten',ev.guests]].map(x=>`<div><div class="kicker" style="color:#627d60">${x[0]}</div><h3 style="margin:9px 0 0;color:#293c2d">${E(x[1])}</h3></div>`).join('')}</div></div><div class="grid two"><div class="card"><div class="kicker">OPDRACHT 1</div><h2 style="margin-top:10px">De uitnodiging</h2><p class="muted tiny">Schrijf een warm, duidelijk bericht. Laat het door de docent nakijken voor het versturen.</p>${edit('inv','title','Titel',i.title)}${edit('inv','body','Uitnodigingstekst',i.body,'textarea')}<button class="btn ghost" data-act="print-inv">Print / opslaan als PDF ↗</button><div class="print-page"><span class="print-logo">MARIS COLLEGE · GASTHEERSCHAP</span><h2 style="margin:20px 0">${E(i.title)}</h2><p>${E(i.body).replace(/\n/g,'<br>')}</p><p><strong>${E(ev.date)}</strong> · ${E(ev.time)}<br>${E(ev.place)}</p><p style="font-style:italic">Met vriendelijke groet, de leerlingen van Maris College Bohemen</p></div></div>
<div class="card"><div class="kicker">OPDRACHT 2</div><h2 style="margin-top:10px">De menukaart</h2><p class="muted tiny">De suggesties kun je aanpassen. Laat de docent de werkelijke ingrediënten en allergenen controleren.</p>${edit('menu','title','Titel',m.title)}${edit('menu','savoury','Hartige hapjes (één per regel)',m.savoury,'textarea')}${edit('menu','sweet','Zoete hapjes (één per regel)',m.sweet,'textarea')}${edit('menu','drinks','Dranken (één per regel)',m.drinks,'textarea')}${edit('menu','allergens','Allergenen- / informatietekst',m.allergens,'textarea')}<button class="btn ghost" data-act="print-menu">Print / opslaan als PDF ↗</button><div class="print-page"><span class="print-logo">MARIS COLLEGE · HIGH TEA</span><h2 style="margin:17px 0">${E(m.title)}</h2>${[['Hartig',m.savoury],['Zoet',m.sweet],['Dranken',m.drinks]].map(x=>`<h3 style="margin:13px 0 5px">${E(x[0])}</h3><p style="margin:0">${E(x[1]).replace(/\n/g,'<br>')}</p>`).join('')}<p style="font-size:11px;margin-top:17px">${E(m.allergens)}</p></div></div></div>
<img class="photo-banner" src="assets/images/high-tea.webp" alt="Inspiratie voor een feestelijk gedekte high tea" width="1536" height="1024" loading="lazy"><div class="section-head"><h2>Begroting & eigen taak</h2></div><div class="grid two"><div class="card"><div class="flex-between"><h3>Mijn boodschappenbegroting</h3>${tag(money(budgetTotal),'green')}</div><p class="muted tiny">Vul aantallen en eenheidsprijzen in. Dit zijn geen actuele winkelprijzen; onderzoek die zelf of met je groep.</p><div style="overflow-x:auto"><table class="score-table"><thead><tr><th>Product</th><th>Aantal</th><th>Prijs/stuk (€)</th><th></th></tr></thead><tbody>${(plan.budget||[]).map((x,idx)=>`<tr><td><input style="width:100%;min-width:100px;background:#ffffff;border:1px solid #405744;border-radius:8px;padding:8px;color:#254b37" data-budget="item" data-index="${idx}" value="${E(x.item)}" aria-label="Product ${idx+1}"></td><td><input style="width:65px;background:#ffffff;border:1px solid #405744;border-radius:8px;padding:8px;color:#254b37" type="number" min="0" step="0.5" data-budget="qty" data-index="${idx}" value="${E(x.qty)}" aria-label="Aantal ${idx+1}"></td><td><input style="width:90px;background:#ffffff;border:1px solid #405744;border-radius:8px;padding:8px;color:#254b37" type="number" min="0" step="0.01" data-budget="price" data-index="${idx}" value="${E(x.price)}" aria-label="Prijs ${idx+1}"></td><td><button class="btn ghost small" data-act="delete-budget" data-id="${idx}" title="Verwijder regel" aria-label="Verwijder product ${idx+1}">×</button></td></tr>`).join('')}</tbody></table></div><div class="button-row" style="margin-top:11px">${button('Product toevoegen','add-budget','ghost')}</div><div class="callout" style="margin-top:12px"><strong>Begrote inkoopkosten: ${money(budgetTotal)}</strong><br>${guestN>0?'Per gast bij '+guestN+' gasten: '+money(budgetTotal/guestN):'Aantal gasten nog onbekend; kosten per gast volgen later.'}</div></div><div class="card"><h3>Mijn taak en draaiboek</h3><div class="field"><label>Mijn rol tijdens de high tea</label><input data-scope="plan" data-key="role" value="${E(plan.role)}" placeholder="Bijv. ontvangst, keuken, bediening"></div><div class="field"><label>Taakplanning, materialen en afspraken</label><textarea data-scope="plan" data-key="notes" placeholder="Voor de high tea regel ik... Tijdens de ontvangst... Na afloop...">${E(plan.notes)}</textarea></div><div class="callout">De docent controleert of alle taken verdeeld zijn, of er voldoende materialen zijn en of de planning met Nolenshage is afgestemd.</div></div></div>
<div class="section-head"><h2>De organisatie van het evenement</h2></div><div class="grid three">${[['📩','Uitnodiging','Maak en controleer de uitnodiging. Versturen pas na goedkeuring.'],['🫖','Menukaart','Kies hartig en zoet, controleer aanbod en allergenen.'],['🛒','Boodschappen','Bereken hoeveel porties en ingrediënten nodig zijn.'],['🪑','Opstelling','Plan tafels, routing en toegankelijkheid.'],['🤝','Taken','Verdeel rollen voor ontvangst, koken, bediening en opruimen.'],['✅','Go / no-go','Laat de docent alle keuzes en veiligheid controleren.']].map(x=>`<div class="card"><div class="iconcard">${x[0]}</div><h3 style="margin:12px 0 7px">${x[1]}</h3><p class="muted tiny">${x[2]}</p></div>`).join('')}</div><div class="callout warn" style="margin-top:20px"><b>Belangrijk:</b> vraag dieetwensen via de contactpersoon van Nolenshage, check allergenen en voedselveiligheid met de school, houd hete dranken buiten botsroutes en maak geen herkenbare foto’s van gasten zonder geldige toestemming.</div>`;}
function rubricTable(displayScores=false){let c=calc();return `<table class="score-table"><thead><tr><th>Onderdeel</th><th>Weging</th><th>Behaald</th></tr></thead><tbody>${c.parts.map(p=>`<tr><td><strong>${E(p.title)}</strong><br><span class="smallprint">${E(p.sub)}</span></td><td>${p.weight} p</td><td>${p.complete?`${nfmt(p.score)} / ${p.weight}`:'Nog niet compleet'}</td></tr>`).join('')}<tr><td><strong>Totaal</strong></td><td><strong>100 p</strong></td><td><strong>${c.ready?nfmt(c.total)+' / 100':'Nog niet definitief'}</strong></td></tr><tr><td><strong>Praktijkcijfer</strong></td><td>1,0 t/m 10,0</td><td><strong style="font-size:22px;color:#286343">${c.ready?nfmt(c.grade):'—'}</strong></td></tr></tbody></table>`;}
function renderRubric(){let r=DATA.rubric;return title('Objectief en transparant','Zo ontstaat je praktijkcijfer','Alle praktijkonderdelen hebben vaste criteria. De docent beoordeelt per criterium van 0 tot en met 3; de app rekent de afgesproken weging om naar maximaal 100 punten.')+
`<div class="grid two"><div class="card"><h2>De puntenverdeling</h2>${rubricTable()}<div class="callout" style="margin-top:16px"><strong>Formule</strong><br>Praktijkcijfer = 1,0 + 9,0 × (behaalde gewogen punten ÷ 100). Afronding op één decimaal. Voorbeeld: 80,0 punten → <b>8,2</b>.</div><p class="smallprint">Een definitief cijfer verschijnt pas als minimaal vijf kookmomenten volledig beoordeeld zijn én alle andere rubriccriteria zijn ingevuld. De SE-theorie heeft een afzonderlijk cijfer.</p></div><div class="card"><h2>Hoe beoordeelt de docent?</h2><div class="check-group">${r.scale.map(a=>`<div class="task"><div class="row-num" style="width:37px;height:37px">${a[0]}</div><div><strong>${E(a[1])}</strong></div></div>`).join('')}</div><p class="muted tiny" style="margin-top:18px">De docent noteert ook feedback en controleert of veilig is gewerkt. Ernstige veiligheidsproblemen worden apart besproken.</p></div></div>
<div class="section-head"><h2>Bekijk alle rubriccriteria</h2></div><div class="tabs">${r.sections.map(x=>`<button class="tab ${ui.rubricTab===x.id?'active':''}" data-act="rubric-tab" data-id="${x.id}">${E(x.title)} · ${x.weight}p</button>`).join('')}</div>${(()=>{const cat=r.sections.find(x=>x.id===ui.rubricTab);return `<div class="card"><div class="flex-between"><h2>${E(cat.title)}</h2>${tag(`${cat.weight} punten`,'gold')}</div><p class="muted tiny">${E(cat.detail)}</p>${cat.criteria.map((x,i)=>`<div class="rubric-row"><div><strong>${i+1}. ${E(x[2])}</strong><small>${E(x[1])}</small></div><div style="text-align:right;color:#c0d4b9">0–3 p</div></div>`).join('')}</div>`;})()}
<div class="section-head"><h2>Voorbeeld van de berekening</h2></div><div class="card"><table class="score-table"><thead><tr><th>Onderdeel</th><th>Voorbeeldscore</th><th>Gewogen punten</th></tr></thead><tbody><tr><td>Koken: gemiddeld 38/48</td><td>38 ÷ 48 × 30</td><td>23,75</td></tr><tr><td>Bediening: 16/21</td><td>16 ÷ 21 × 20</td><td>15,24</td></tr><tr><td>Voorbereiding: 9/12</td><td>9 ÷ 12 × 20</td><td>15,00</td></tr><tr><td>High tea: 12/15</td><td>12 ÷ 15 × 20</td><td>16,00</td></tr><tr><td>Portfolio: 7/9</td><td>7 ÷ 9 × 10</td><td>7,78</td></tr><tr><td><b>Totaal</b></td><td>77,77 / 100</td><td><b>Praktijkcijfer 8,0</b></td></tr></tbody></table><p class="smallprint">Het voorbeeld is fictief. De app rekent zelf met ongeronde tussenwaarden.</p></div>`;}
function renderProgress(){const pr=doneTasks(),scores=calc(),recent=[...P().quizHistory].reverse().slice(0,7);return title('Leren / afvinken / terugkijken','Mijn voortgang','Alle afgevinkte taken, oefentoetsen en portfolio-opdrachten komen hier samen. Exporteer jouw voortgang om aan de docent te laten zien.')+
`<div class="grid three"><div class="card stat"><span class="label">Taken gereed</span><div class="value">${pr.pct}%</div><span class="sub">${pr.done} / ${pr.total} afgevinkt</span><div class="metric-bar"><div style="width:${pr.pct}%"></div></div></div><div class="card stat"><span class="label">Oefentoetsen afgerond</span><div class="value">${P().quizHistory.length}</div><span class="sub">Tellen niet mee voor praktijkcijfer</span></div><div class="card stat"><span class="label">Praktijkcijfer</span><div class="value">${scores.ready?nfmt(scores.grade):'—'}</div><span class="sub">${scores.ready?'Volledig berekend op deze browser':'Nog niet alle criteria beoordeeld'}</span></div></div><div class="section-head"><h2>De acht aftekenlijsten</h2></div><div class="grid two">${DATA.sessions.map(s=>{let done=s.tasks.filter(t=>P().checks[`${s.id}_${t[0]}`]).length;return `<button class="item-card" data-act="open-lesson" data-id="${s.id}"><div class="flex-between"><span class="kicker">LES ${s.id}</span><span class="pill">${done}/${s.tasks.length}</span></div><div class="title">${E(s.title)}</div><div class="metric-bar"><div style="width:${percent(done,s.tasks.length)}%"></div></div></button>`}).join('')}</div><div class="section-head"><h2>Interactieve lessen · zelf nagekeken</h2></div><div class="card">${DATA.sessions.map(x=>{let p=getCheckedLesson(x.id);return `<div class="rubric-row"><strong>Les ${x.id} · ${E(x.title)}</strong><span>${p?`${p.score}/5 goed · ${E(p.date)}`:"Nog niet gemaakt"}</span></div>`}).join('')}</div><div class="section-head"><h2>Laatste oefentoetsen</h2></div><div class="card">${recent.length?`<table class="score-table"><thead><tr><th>Onderdeel</th><th>Datum</th><th>Score</th></tr></thead><tbody>${recent.map(x=>`<tr><td>${E(x.filter==='all'?'Gemengde SE-toets':cData(x.filter)?.title||x.filter)}</td><td>${E(x.date)}</td><td><b>${x.percentage}%</b> (${x.points}/${x.total})</td></tr>`).join('')}</tbody></table>`:'<p class="muted">Je hebt nog geen oefentoets gemaakt.</p>'}</div><div class="section-head"><h2>Mijn reflectie</h2></div><div class="card"><div class="field"><label>Waar ben je trots op, en wat wil je verbeteren?</label><textarea data-scope="profile" data-key="reflection" placeholder="Ik heb geleerd om... De volgende keer wil ik...">${E(P().reflection||'')}</textarea></div><div class="button-row">${button('Download mijn portfolio (.json)','export-student','')}${button('Print mijn overzicht','print-progress','ghost')}</div><p class="smallprint">Een exportbestand kun je aan je docent geven. Je gegevens worden niet automatisch verzonden of gedeeld.</p></div>`;}
function renderTeacher(){if(!isTeacher)return renderHome();const r=DATA.rubric.sections.find(x=>x.id===ui.teacherSection),res=calc(),profiles=Object.keys(state.profiles).sort((a,b)=>a.localeCompare(b,'nl'));let rows=()=>r.criteria.map((x,i)=>{let val=rValue(r.id,x[0],ui.cook);return `<div class="rubric-row"><div><strong>${i+1}. ${E(x[2])}</strong><small>${E(x[1])}</small></div><select class="rubric-select" aria-label="Score ${E(x[2])}" data-score="${r.id}" data-criterion="${x[0]}" data-cook="${ui.cook}"><option value="" ${val===null?'selected':''}>— kies</option>${[0,1,2,3].map(n=>`<option value="${n}" ${n===val?'selected':''}>${n} punten</option>`).join('')}</select></div>`}).join('');
return title('Docentenomgeving · pilot','Beoordeling & leerlingen','Beoordeel criterium voor criterium. Het praktijkcijfer verschijnt pas nadat vijf volledige kookmomenten én alle overige onderdelen zijn beoordeeld.')+
`<div class="callout warn" style="margin-bottom:18px"><b>Open docentomgeving:</b> er is bewust geen inlog of wachtwoord. Cijfers en rubrics worden alleen in de browser opgeslagen en zijn niet beschermd tegen andere gebruikers van hetzelfde apparaat. Gebruik leerlingcodes, bewaar exports op een beveiligde schoollocatie en deel de docentlink bewust.</div>
<div class="split"><div><div class="card"><div class="flex-between"><h2>Beoordeel: ${E(state.active)}</h2>${button('Voeg leerling toe','add-profile','ghost')}</div><div class="field"><label>Selecteer leerling of code</label><select data-uivalue="activeProfile" class="select-light">${profiles.map(p=>`<option value="${E(p)}" ${p===state.active?'selected':''}>${E(p)}</option>`).join('')}</select></div><div class="tabs">${DATA.rubric.sections.map(x=>`<button class="tab ${ui.teacherSection===x.id?'active':''}" data-act="teacher-section" data-id="${x.id}">${E(x.title)}</button>`).join('')}</div>${r.id==='cooking'?`<div class="field"><label>Welk kookmoment beoordeel je?</label><select class="select-light" data-uivalue="cook">${(isPeriod1?DATA.sessions.map(x=>({title:x.title})):DATA.recipes).map((x,i)=>`<option value="${i+1}" ${ui.cook===i+1?'selected':''}>Kookmoment ${i+1} · ${E(x.title)}</option>`).join('')}</select></div>`:''}<div class="flex-between" style="margin-bottom:16px"><h3>${E(r.title)}</h3>${tag(r.id==='cooking'?'16 criteria × 3 = max. 48':`${r.criteria.length} criteria × 3 = max. ${r.criteria.length*3}`,'gold')}</div><p class="muted tiny">${E(r.detail)}</p>${rows()}<div class="callout" style="margin-top:18px"><b>Scoreankers:</b> 0 = niet uitgevoerd/onveilig; 1 = veel hulp; 2 = grotendeels zelfstandig; 3 = zelfstandig, correct, veilig en verzorgd. Beoordeel bewijs, niet alleen inzet.</div></div><div class="card" style="margin-top:17px"><h3>Docentnotities</h3><div class="field"><label>Feedback / aandachtspunten bij deze leerling</label><textarea data-scope="profile" data-key="teacherNotes">${E(P().teacherNotes||'')}</textarea></div></div></div><div><div class="card"><h3>Actuele cijferberekening</h3>${rubricTable()}<div class="button-row" style="margin-top:15px">${button('Print beoordelingsrapport','print-report','ghost')}${button('Exporteer als CSV','export-csv','ghost')}</div></div><div class="card" style="margin-top:17px"><h3>Beheer leerlingen</h3><p class="muted tiny">Op dit apparaat staan ${profiles.length} leerlingprofielen. Je kunt een portfolio van een leerling importeren via de instellingen.</p>${profiles.map(p=>`<button class="row-lesson" data-act="switch-profile" data-id="${E(p)}" style="margin-bottom:7px"><div class="row-num">${E(p.slice(0,2).toUpperCase())}</div><div><strong>${E(p)}</strong><small>${p===state.active?'Geselecteerd':'Klik voor beoordeling'}</small></div>↗</button>`).join('')}<div style="margin-top:14px" class="button-row">${button('Leerling toevoegen','add-profile','ghost')}${button('Importeer portfolio','open-import','ghost')}</div></div><div class="card" style="margin-top:17px"><h3>Beoordelingsbeleid</h3><p class="smallprint">Deze rubric is een nieuw voorstel, afgeleid van de oorspronkelijke kookaftekenlijst (48 punten) en de twee aangeleverde eindformulieren. Die oudere formulieren hebben afwijkende categorieën; gebruik daarom voor dit achtbijeenkomstenprogramma consequent dit 100-puntenmodel.</p>${button('Open docenthandleiding','go-guide','ghost')} ${button('Alle originele bestanden','go-documents','ghost')}</div><div class="card" style="margin-top:17px"><h3>Interactieve zelftoetsen · ${E(state.active)}</h3><p class="smallprint">Vijf vragen per bijeenkomst. Dit is oefenstof en telt niet mee voor het praktijkcijfer.</p>${DATA.sessions.map(x=>{let check=getCheckedLesson(x.id);return `<div class="rubric-row"><strong>Les ${x.id}: ${E(x.title)}</strong><span>${check?check.score+'/5':'Nog niet'}</span></div>`;}).join('')}</div></div></div>`;}
function renderGuide(){if(!isTeacher)return renderHome();return title('Overdraagbaar lesprogramma','Docentenhandleiding','Een collega kan met dit stappenplan de acht bijeenkomsten draaien. Alle inhoudelijke onderdelen zijn uit bestaande materialen overgenomen of als nieuw voorstel duidelijk benoemd.')+
`<div class="grid two"><div class="card"><h2>Didactische uitgangspunten</h2><ol class="detail-list"><li>Doelgroep: 4 kader E&O; praktijkgericht en kortcyclisch.</li><li>Acht bijeenkomsten, voorbeeldtijd 150 minuten (schoolrooster leidend).</li><li>Elke les: starten, theorie, voordoen, zelf oefenen, schoonmaken, reflecteren.</li><li>Leerlingen houden zelf een checklist bij, maken per bijeenkomst vijf interactieve oefenvragen en kijken deze zelf na; oefenscores tellen niet mee voor het praktijkcijfer.</li><li>De docent kent punten toe via de praktijkrubric.</li><li>Een praktijkcijfer wordt pas definitief bij minimaal vijf compleet beoordeelde kookmomenten plus alle overige onderdelen.</li><li>SE-theorie: H1, H2, H4 en H6. Praktijkkennis: H3, H5 en H7.</li></ol></div><div class="card"><h2>Materialen & voorbereiding</h2><ol class="detail-list"><li>Reserveer keuken, ovens, tafels, servies, pannen, snijplanken en schoonmaakmiddelen.</li><li>Check schorten, dichte schoenen, HACCP-/schoolinstructies en EHBO/BHV.</li><li>Leg recepten en ingrediënten per tweetal klaar; school controleert hoeveelheden.</li><li>Bereid een station voor tafel indekken, poleren, borden dragen en thee schenken voor.</li><li>Houd leerlingcodes en beoordelingsformulieren in een beveiligde schoolomgeving.</li><li>Stem via de contactpersoon van Nolenshage datum, locatie, toegankelijkheid, aantallen, dieetwensen en vervoer af.</li></ol></div></div>
<div class="section-head"><h2>Leskaart voor iedere bijeenkomst</h2></div>${DATA.sessions.map(s=>`<div class="card" style="margin-bottom:13px"><div class="flex-between"><div><span class="kicker">BIJEENKOMST ${s.id} / ${E(s.type)}</span><h3 style="font-size:19px;margin:7px 0">${E(s.title)} · ${E(s.subtitle)}</h3></div>${tag(s.id===8?'Eindopdracht':'Leskaart','green')}</div><p class="muted tiny"><b>Leerdoel:</b> ${E(s.goal)}</p><div class="grid two"><div><h4>Opbouw</h4>${s.blocks.map(x=>`<p class="smallprint" style="margin-bottom:6px"><b>${E(x[1])} · ${E(x[0])}:</b> ${E(x[2])}</p>`).join('')}</div><div><h4>Controle en bewijs</h4>${s.tasks.map(x=>`<p class="smallprint" style="margin-bottom:6px">□ ${E(x[1])}</p>`).join('')}</div></div></div>`).join('')}
<div class="section-head"><h2>Praktijkcijfer en afspraken</h2></div><div class="card">${rubricTable()}<p class="smallprint">Per kookmoment 16 criteria × 0–3 punten = maximaal 48. Neem het gemiddelde van minimaal 5 volledig beoordeelde kookmomenten en reken om naar 30 gewogen punten. Overige categorieën: score gedeeld door hun eigen maximum maal de weging. Totaal maximaal 100; cijfer = 1 + 9 × totaal/100; afronden op één decimaal. Niet-ingevuld is géén nul: cijfers blijven voorlopig totdat alle onderdelen compleet zijn.</p><p class="smallprint">Bij onveilig handelen onderbreekt de docent de opdracht en maakt een veiligheidsafspraak. Een score van 0 of onvoldoende veiligheidsbeheersing verdient gerichte feedback en zo nodig een herkansingsmoment; bepaal het formele beleid in het PTA.</p></div>
<div class="section-head"><h2>High tea: operationeel draaiboek</h2></div><div class="grid two"><div class="card"><h3>Vooraf regelen</h3><ol class="detail-list"><li>Contactpersoon Nolenshage: datum/tijd/locatie en verwachtingen bevestigen.</li><li>Reken aantal gasten en leerlingen om naar porties, plus redelijke reserve.</li><li>Inventariseer allergenen en dieetwensen zorgvuldig en discreet.</li><li>Uitnodiging en menukaart door docent laten goedkeuren en verspreiden.</li><li>Voedselinkoop, koeling, vervoer, stroom en schoonmaak regelen.</li><li>Rolkaartjes maken: chef, ontvangst, bediening, tafels, logistiek, fotografie alleen met toestemming.</li><li>GO/NO-GO: ruimte, producten, hygiëne, toegankelijkheid en BHV geregeld.</li></ol></div><div class="card"><h3>Tijdens en na de high tea</h3><ol class="detail-list"><li>Leerlingen bouwen de zaal volgens routingplan op.</li><li>Docent checkt hygiëne, temperatuur, allergenen en presentatie.</li><li>Ontvangstteam begeleidt de gasten naar hun plek.</li><li>Bediening vraagt voorkeuren en serveert in rustig tempo.</li><li>Docent observeert iedere leerling volgens de rubric.</li><li>Ruim op volgens schoonmaakchecklist en bedank de gasten.</li><li>Evalueer en leg het cijfer plus feedback vast.</li></ol><p class="smallprint">Alle tijden zijn indicatief. De definitieve datum is nog niet bekend.</p></div></div>
<div class="section-head"><h2>Bronnen en materiaalverantwoording</h2></div><div class="card"><p class="smallprint"><b>1. HBR P1, 3e druk, Samenvatting.docx:</b> eigen herformuleringen voor de hoofdstukken 1–7. Alleen 1, 2, 4 en 6 zijn aangemerkt als SE-theorie op basis van de informatie van de vakdocent.<br><b>2. Gastheerschap les 1 'broodje kip'.pptx:</b> persoonlijke hygiëne, snijplanken, mise-en-place, afwas, controle, broodje kip en tafel dekken.<br><b>3. Gastheerschap les 2 'mini pizza en appelflappen'.pptx:</b> twee bereidingen, vaste keukenstappen en instructievideo.<br><b>4. Gastheerschap les 3 'video maken, recept, activiteit zoeken, theorie maken'.pptx:</b> eigen recept, video en zelfstandig werken.<br><b>5. Aftekenlijst Gastheerschap onderdeel koken.docx:</b> 16 criteria × 3 = 48 per kookmoment.<br><b>6. Beoordelingsformulier eindcijfer.docx:</b> lessen, kookvaardigheden, ouderenbrunch, uitnodiging, menukaart, voorbereiding en opruimen. De oude formulieren zijn vertaald naar de transparante rubric voor de nieuwe high tea.</p><p class="smallprint"><b>Nieuw ontwikkeld voor deze versie:</b> mini-quiches, scones, muffins, 8-bijeenkomstenroute, oefenvragen, puntenweging en high-teaplan. Deze onderdelen zijn lesvoorstellen en geen letterlijke inhoud uit de methode.</p></div>`;}
function renderSettings(){return title('Bewaren / delen / aanpassen','Gegevens & hulp','De app werkt zonder account. Voortgang wordt in de browser van dit apparaat bewaard, niet op een centrale server. Gebruik de export om werk te verplaatsen of te delen met je docent.')+
`<div class="grid two"><div class="card"><h2>Mijn profiel</h2><div class="field"><label>Actieve leerling(code)</label><select class="select-light" data-uivalue="activeProfile">${Object.keys(state.profiles).map(p=>`<option value="${E(p)}" ${p===state.active?'selected':''}>${E(p)}</option>`).join('')}</select></div><div class="button-row">${button('Nieuw profiel','add-profile','ghost')}${button('Download portfolio','export-student','')}${button('Importeer portfolio','open-import','ghost')}</div><p class="smallprint">Gebruik een anonieme leerlingcode in plaats van volledige persoonsgegevens. Gebruik de docentomgeving voor beoordelen, niet een openbaar leerlingapparaat.</p></div><div class="card"><h2>Back-up en herstel</h2><p class="muted tiny">Maak een JSON-back-up op je eigen apparaat. Een docent kan klasgegevens als CSV exporteren. Bij het importeren van een portfolio wordt het genoemde leerlingprofiel toegevoegd of na bevestiging vervangen.</p><div class="button-row">${button('Exporteer volledige back-up','export-all','ghost')}${button('Importeer een JSON-bestand','open-import','ghost')}</div><input hidden type="file" id="json-import" accept=".json,application/json"/><div class="callout warn" style="margin-top:17px">Online delen van een HTML-pagina is <b>niet hetzelfde</b> als online opslaan van afvinkjes of cijfers. Iedere leerling gebruikt zijn eigen browseropslag; docent en leerling synchroniseren in deze versie alleen via export/import.</div></div></div>
${isTeacher?`<div class="section-head"><h2>Organisatiegegevens high tea</h2></div><div class="card"><p class="smallprint">Alleen op dit apparaat opgeslagen. Zet de definitieve gegevens ook in het gedeelde schoolprogramma voordat je het naar leerlingen stuurt.</p><div class="formrow">${[['eventDate','Datum (bijv. donderdag 18 maart 2027)'],['eventTime','Tijd'],['eventPlace','Locatie'],['guestCount','Aantal gasten'],['teacher','Verantwoordelijke docent']].map(x=>`<div class="field"><label>${x[1]}</label><input data-scope="meta" data-key="${x[0]}" value="${E(state.meta[x[0]]||'')}" placeholder="Nog te bevestigen"></div>`).join('')}</div></div>`:''}
<div class="section-head"><h2>Gebruik en privacy</h2></div><div class="card"><ol class="detail-list"><li><b>Leerlingen:</b> open index.html of de gehoste indexpagina, kies een leerlingcode, vink lesopdrachten af en maak theorievragen.</li><li><b>Docent:</b> open docent.html op de eigen schoolcomputer. Beoordeel met de rubric en bekijk de resultaten.</li><li><b>Portfolio delen:</b> student downloadt JSON, docent importeert dat bestand in docent.html. Deel geen gegevens van andere leerlingen.</li><li><b>Online gebruik:</b> plaats de map op een HTTPS-webserver of GitHub Pages. Bewaar alle bestanden bij elkaar. Voor echte accounts, beveiligde beoordelingen en directe synchronisatie is een aparte backend nodig.</li><li><b>Veiligheid:</b> de docent blijft verantwoordelijk voor recepten, dieetwensen en feitelijke uitvoering.</li></ol></div>`;}
function renderPrintable(){let ev=eventInfo(),p=P();let titleHtml=`<span class="print-logo">MARIS COLLEGE BOHEMEN · GASTHEERSCHAP</span>`;if(ui.print==='inv')return `<div class="print-page">${titleHtml}<h2>${E(p.invitation.title)}</h2><p>${E(p.invitation.body).replace(/\n/g,'<br>')}</p><p><b>${E(ev.date)} · ${E(ev.time)}</b><br>${E(ev.place)}</p><p>Met vriendelijke groet,<br>de leerlingen van Maris College Bohemen</p></div>`;
if(ui.print==='menu')return `<div class="print-page">${titleHtml}<h2>${E(p.menu.title)}</h2>${[['Hartige hapjes',p.menu.savoury],['Zoete hapjes',p.menu.sweet],['Dranken',p.menu.drinks]].map(x=>`<h3>${E(x[0])}</h3><p>${E(x[1]).replace(/\n/g,'<br>')}</p>`).join('')}<p><small>${E(p.menu.allergens)}</small></p></div>`;
if(ui.print==='report')return `<div class="print-page">${titleHtml}<h2>Praktijkbeoordeling – ${E(state.active)}</h2>${rubricTable()}<p><strong>Feedback:</strong> ${E(p.teacherNotes)}</p><p>Docent: ____________________ &nbsp; Datum: ____________________</p></div>`;
if(ui.print==='recipe'){let r=recipe();return `<div class="print-page">${titleHtml}<h2>${E(r.title)}</h2><p>${E(r.makes)} · ${E(r.time)}</p><h3>Ingrediënten</h3><ul>${r.ingredients.map(x=>`<li>${E(x)}</li>`).join('')}</ul><h3>Stappen</h3><ol>${r.steps.map(x=>`<li>${E(x)}</li>`).join('')}</ol><p><small>${E(r.allergens)}</small></p></div>`;}
if(ui.print==='progress'){let d=doneTasks();return `<div class="print-page">${titleHtml}<h2>Voortgang – ${E(state.active)}</h2><p>${d.done} van ${d.total} taken afgerond</p>${DATA.sessions.map(s=>`<h3>Bijeenkomst ${s.id}: ${E(s.title)}</h3><ul>${s.tasks.map(t=>`<li>${P().checks[`${s.id}_${t[0]}`]?'✓':'□'} ${E(t[1])}</li>`).join('')}</ul>`).join('')}<p>Reflectie: ${E(P().reflection||'')}</p></div>`;}
return'';}
// Browser events and exports
function downloadText(name,content,type='application/json'){const b=new Blob([content],{type});const url=URL.createObjectURL(b);let a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportStudent(){downloadText('gastheerschap-periode-'+PERIOD+'-portfolio-'+state.active.replace(/[^a-z0-9_-]/gi,'-')+'.json',JSON.stringify({kind:'gastheerschap-student-v1',period:PERIOD,name:state.active,profile:P(),exportedAt:new Date().toISOString()},null,2));toast('Portfolio gedownload.');}
function exportAll(){downloadText('gastheerschap-periode-'+PERIOD+'-backup.json',JSON.stringify({kind:'gastheerschap-full-v1',period:PERIOD,state,exportedAt:new Date().toISOString()},null,2));toast('Back-up gedownload.');}
function exportCSV(){if(!isTeacher)return;const line=arr=>arr.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(';');let csv=[line(['Leerlingcode','Koken /30','Bediening /20','Voorbereiding /20','High tea /20','Portfolio /10','Totaal /100','Praktijkcijfer','Volledig',...DATA.sessions.map(s=>'Zelfcheck les '+s.id+' /5')])];let old=state.active;Object.keys(state.profiles).forEach(n=>{state.active=n;let r=calc();csv.push(line([n,...r.parts.map(x=>x.complete?nfmt(x.score):'onvolledig'),r.ready?nfmt(r.total):'',r.ready?nfmt(r.grade):'',r.ready?'ja':'nee',...DATA.sessions.map(s=>getCheckedLesson(s.id)?.score??'')]));});state.active=old;downloadText('gastheerschap-cijferoverzicht.csv','\uFEFF'+csv.join('\r\n'),'text/csv;charset=utf-8');toast('Cijferoverzicht gedownload.');}
function printView(which){ui.print=which;render();document.body.classList.add('only-print-mode');setTimeout(()=>{window.print();setTimeout(()=>{document.body.classList.remove('only-print-mode');ui.print='';},450);},75);}
function resetQuiz(){ui.quiz=null;render();}
function addProfile(){let name=prompt('Kies een leerlingcode (bijv. 4K-07 of je voornaam):');if(name===null)return;name=name.trim().slice(0,40);if(!name){toast('Vul een leerlingcode in.');return;}if(!state.profiles[name])state.profiles[name]=defaultProfile();state.active=name;save();render();toast('Profiel geselecteerd: '+name);}
function chooseProfile(){let names=Object.keys(state.profiles);let choice=prompt('Kies of typ een leerlingcode. Bestaande profielen op dit apparaat:\n'+names.join(', '),state.active);if(choice===null)return;choice=choice.trim().slice(0,40);if(!choice)return;if(!state.profiles[choice]){if(!confirm('Nieuw profiel '+choice+' aanmaken?'))return;state.profiles[choice]=defaultProfile();}state.active=choice;save();render();}
function handleAction(act,el){if(act==='choose-profile')return chooseProfile();if(act==='add-profile')return addProfile();if(act==='go-programme')return navTo('programme');if(act==='go-quiz')return navTo('quiz');if(act==='go-hightea')return navTo('hightea');if(act==='go-theory')return navTo('theory');if(act==='go-interactive')return navTo('interactive');if(act==='interactive-session'){ui.interactiveLesson=ui.lesson;ui.interactiveAnswers={};ui.interactiveChecked=false;return navTo('interactive');}if(act==='interactive-lesson'){ui.interactiveLesson=Number(el.dataset.id);ui.interactiveAnswers={};ui.interactiveChecked=false;return render();}if(act==='return-programme'){ui.lesson=ui.interactiveLesson;return navTo('programme');}if(act==='retry-interactive'){ui.interactiveAnswers={};ui.interactiveChecked=false;return render();}if(act==='check-interactive'){let unit=interactionSource(ui.interactiveLesson);if(unit.questions.some((q,i)=>!Number.isInteger(ui.interactiveAnswers[i]))){toast('Beantwoord eerst alle vijf de vragen.');return;}ui.interactiveChecked=true;let score=unit.questions.filter((q,i)=>ui.interactiveAnswers[i]===q[2]).length;P().lessonChecks??={};P().lessonChecks[unit.id]={score,total:unit.questions.length,answers:{...ui.interactiveAnswers},date:new Date().toLocaleDateString('nl-NL')};save();render();return;}if(act==='documents-filter'){ui.documentsFilter=el.dataset.id;return render();}if(act==='go-guide')return navTo('guide');if(act==='go-documents')return navTo('documents');if(act==='open-lesson'){ui.lesson=Number(el.dataset.id);return navTo('programme');}if(act==='chapter'){ui.chapter=el.dataset.id;return render();}if(act==='rubric-tab'){ui.rubricTab=el.dataset.id;return render();}if(act==='teacher-section'){ui.teacherSection=el.dataset.id;return render();}if(act==='recipe'){ui.recipe=el.dataset.id;return render();}if(act==='recipe-session'){ui.recipe=lesson().cook;return navTo('kitchen');}if(act==='go-recipe-lesson'){ui.lesson=recipe().meeting;return navTo('programme');}if(act==='theory-session'){ui.chapter=lesson().theory[0];return navTo('theory');}if(act==='quiz-chapter'){ui.quizFilter=el.dataset.id;return navTo('quiz');}if(act==='start-quiz'){quizMake();return render();}if(act==='restart-quiz'){ui.quiz=null;return render();}if(act==='quiz-answer'){const qz=ui.quiz;if(!qz||qz.answered!==null)return;let idx=Number(el.dataset.id);qz.answered=idx;if(qz.items[qz.index].options[idx].correct)qz.points++;return render();}if(act==='quiz-next'){let qz=ui.quiz;if(qz.answered===null)return;if(qz.index+1<qz.items.length){qz.index++;qz.answered=null;}else{qz.finished=true;let score={filter:ui.quizFilter,date:new Date().toLocaleDateString('nl-NL'),points:qz.points,total:qz.items.length,percentage:percent(qz.points,qz.items.length)};P().quizHistory.push(score);save();}return render();}
if(act==='check-table'){let got=DATA.tableExercise.filter((x,i)=>ui.tableAnswers[i]===x.correct).length;ui.tableFeedback={ok:got,total:DATA.tableExercise.length};P().table={...ui.tableFeedback,date:new Date().toISOString()};save();return render();}
if(act==='switch-profile'){state.active=el.dataset.id;save();return render();}if(act==='open-import'){let input=document.getElementById('json-import');if(!input){navTo('settings');input=document.getElementById('json-import');}input?.click();return;}
if(act==='add-budget'){(P().highteaPlan||(P().highteaPlan={role:'',notes:'',budget:[]})).budget.push({item:'',qty:1,price:0});save();return render();}if(act==='delete-budget'){if(P().highteaPlan?.budget){P().highteaPlan.budget.splice(Number(el.dataset.id),1);save();render();}return;}if(act==='export-student')return exportStudent();if(act==='export-all')return exportAll();if(act==='export-csv')return exportCSV();if(act==='print-inv')return printView('inv');if(act==='print-menu')return printView('menu');if(act==='print-report')return printView('report');if(act==='print-progress')return printView('progress');if(act==='print-recipe')return printView('recipe');}
document.addEventListener('click',ev=>{const design=ev.target.closest('button[data-design]');if(design){const value=design.dataset.design;if(!['1','2','3'].includes(value))return;try{localStorage.setItem('maris-gastheerschap-design',value);}catch{}document.body.dataset.design=value;document.querySelectorAll('button[data-design]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.design===value)));return;}let link=ev.target.closest('[data-file-action]');let nav=ev.target.closest('[data-nav]');if(nav){navTo(nav.dataset.nav);return;}let b=ev.target.closest('[data-act]');if(b){handleAction(b.dataset.act,b);}});
document.addEventListener('change',ev=>{let el=ev.target;
 if(el.matches('[data-lunch-count]')){const n=Number(el.value);if(el.value!==''&&Number.isInteger(n)&&n>=0&&n<=100)P().highteaPlan.studentCount=n;else delete P().highteaPlan.studentCount;save();setTimeout(render,0);return;}
 if(el.id==='mobile-view-select'){navTo(el.value);return;}
 if(el.matches('[data-lesson-answer]')){if(!ui.interactiveChecked)ui.interactiveAnswers[Number(el.dataset.lessonAnswer)]=Number(el.value);return;}
 if(el.matches('[data-budget]')){let list=(P().highteaPlan||(P().highteaPlan={role:'',notes:'',budget:[]})).budget;let obj=list[Number(el.dataset.index)];if(obj){obj[el.dataset.budget]=el.dataset.budget==='item'?el.value:Math.max(0,Number(el.value)||0);save();render();}return;}
 if(el.matches('[data-check]')){P().checks[el.dataset.check]=el.checked;save();render();return;}
 if(el.matches('[data-table]')){ui.tableAnswers[el.dataset.table]=el.value;ui.tableFeedback=null;return;}
 if(el.matches('[data-score]')){if(!isTeacher)return;let sec=el.dataset.score,key=el.dataset.criterion,cook=el.dataset.cook;let root=P().rubric;if(!root[sec])root[sec]={};let obj=sec==='cooking'?(root.cooking[cook]??={ }):root[sec];if(el.value==='')delete obj[key];else obj[key]=Number(el.value);save();render();return;}
 if(el.matches('[data-uivalue]')){let k=el.dataset.uivalue;if(k==='activeProfile'){if(state.profiles[el.value]){state.active=el.value;save();render();}return;}if(k==='cook')ui.cook=Number(el.value);else if(k==='quizCount')ui.quizCount=Number(el.value);else ui[k]=el.value;render();return;}
 if(el.id==='json-import'&&el.files?.[0]){let file=el.files[0];let reader=new FileReader();reader.onload=()=>{try{let x=JSON.parse(reader.result);if(String(x.period||'2')!==PERIOD){toast('Dit bestand hoort bij een andere periode. Wissel eerst van periode.');return;}if(x.kind==='gastheerschap-student-v1'&&x.name&&x.profile){let name=String(x.name).slice(0,40);if(state.profiles[name]&&!confirm('Bestaand profiel '+name+' vervangen door dit bestand?'))return;state.profiles[name]={...defaultProfile(),...x.profile};state.active=name;save();render();toast('Portfolio geïmporteerd.');}else if(x.kind==='gastheerschap-full-v1'&&x.state?.profiles&&x.state.meta){if(!confirm('Volledige back-up laden? Dit vervangt de huidige lokale voortgang.'))return;state=x.state;save();render();toast('Back-up hersteld.');}else toast('Dit is geen geldig Gastheerschap-exportbestand.');}catch(e){toast('Bestand kan niet worden gelezen.');}};reader.readAsText(file);return;}
});
let saveTimer=null;document.addEventListener('input',ev=>{let el=ev.target;if(!el.matches('[data-scope]'))return;let s=el.dataset.scope,key=el.dataset.key,v=el.value;if(s==='lessonNote')P().lessonNotes[key]=v;else if(s==='inv')P().invitation[key]=v;else if(s==='menu')P().menu[key]=v;else if(s==='profile')P()[key]=v;else if(s==='plan'){(P().highteaPlan||(P().highteaPlan={budget:[]}))[key]=v;}else if(s==='meta'&&isTeacher)state.meta[key]=v;clearTimeout(saveTimer);saveTimer=setTimeout(()=>{save();if((s==='inv'||s==='menu')&&ui.view==='hightea'){/* Preview updaten zonder focus te verliezen */let p=el.closest('.card')?.querySelector('.print-page');if(p){let val=P()[s==='inv'?'invitation':'menu'];if(s==='inv'){p.innerHTML=`<span class="print-logo">MARIS COLLEGE · GASTHEERSCHAP</span><h2>${E(val.title)}</h2><p>${E(val.body).replace(/\n/g,'<br>')}</p><p><strong>${E(eventInfo().date)}</strong> · ${E(eventInfo().time)}<br>${E(eventInfo().place)}</p><p>Met vriendelijke groet, de leerlingen van Maris College Bohemen</p>`;}else{p.innerHTML=`<span class="print-logo">MARIS COLLEGE · HIGH TEA</span><h2>${E(val.title)}</h2>${[['Hartig',val.savoury],['Zoet',val.sweet],['Dranken',val.drinks]].map(x=>`<h3>${E(x[0])}</h3><p>${E(x[1]).replace(/\n/g,'<br>')}</p>`).join('')}<p style="font-size:11px">${E(val.allergens)}</p>`;}}}},350);});
window.addEventListener('storage',e=>{if(e.key===K){state=load();render();}});
render();
})();
